    document.querySelectorAll('[data-pay-material]').forEach(button=>{const id=button.dataset.payMaterial;button.textContent='付款记录';const upload=document.createElement('button');upload.className='action';upload.textContent='上传发票';upload.onclick=()=>openInvoiceModal({direction:'进项',project_id:projectId,source_type:'材料',source_id:id});button.after(upload);if(hasInvoice('材料',id)){const badge=document.createElement('span');badge.className='invoice-present';badge.textContent='✓ 已有发票';button.closest('tr').children[1].appendChild(badge)}});document.querySelectorAll('[data-pay-cost]').forEach(button=>{const id=button.dataset.payCost;button.textContent='付款记录';const upload=document.createElement('button');upload.className='action';upload.textContent='上传发票';upload.onclick=()=>openInvoiceModal({direction:'进项',project_id:projectId,source_type:'BOM费用',source_id:id});button.after(upload);if(hasInvoice('BOM费用',id)){button.closest('tr').children[5].innerHTML='<span class="invoice-present">✓ 已有发票</span>'}});
