    const syncSub=()=>{const primary=$('#price-primary').value,current=$('#price-sub').value,items=materialCategories[primary]?.items||[...new Set(materials.map(item=>item.subcategory||item.category).filter(Boolean))].sort();$('#price-sub').innerHTML='<option value="">全部二级品类</option>'+items.map(name=>`<option ${name===current?'selected':''}>${esc(name)}</option>`).join('')};
    const draw=()=>{const query=$('#price-search').value.trim().toLowerCase(),primary=$('#price-primary').value,sub=$('#price-sub').value;const rows=materials.filter(item=>{const itemPrimary=item.primary_category||'待归类',itemSub=item.subcategory||item.category||'';return(!query||`${item.material_code} ${item.material_name} ${item.specification||''}`.toLowerCase().includes(query))&&(!primary||itemPrimary===primary)&&(!sub||itemSub===sub)});$('#price-result-count').textContent=`共 ${rows.length} 项材料`;$('#price-material-body').innerHTML=rows.map(item=>`<tr><td><strong>${esc(item.material_code)}</strong></td><td><span class="price-primary-tag">${esc(item.primary_category||'待归类')}</span><span class="sub">${esc(item.subcategory||item.category||'未设置二级品类')}</span></td><td><strong>${esc(item.material_name)}</strong><span class="sub">${esc(item.specification||'未标防火等级')} · 标准损耗 ${Number(item.loss_rate||0)}%</span><span class="sub">${esc(item.note||'')}</span></td><td>${esc(item.supplier||'—')}</td><td>${esc(item.unit)}</td><td class="amount-col"><strong>${money(item.base_price)}</strong><span class="sub">零星/历史 ${money(item.last_purchase_price||0)}</span></td><td><button class="action" data-edit-price-material="${item.id}">修改</button><button class="action danger-action" data-delete-material="${item.id}">删除</button></td></tr>`).join('')||'<tr><td colspan="7" class="empty">当前分类下暂无材料</td></tr>';document.querySelectorAll('[data-edit-price-material]').forEach(button=>button.onclick=()=>openCatalogMaterialModal(materials.find(item=>item.id==button.dataset.editPriceMaterial)));document.querySelectorAll('[data-delete-material]').forEach(button=>button.onclick=()=>deletePrice(`/api/material-catalog/${button.dataset.deleteMaterial}`,'材料'))};
