    await loadProjects();const [ledgerResult,summaryResult,settings]=await Promise.all([api('/api/invoice-ledger'),api('/api/invoice-monthly-summary'),api('/api/settings')]),all=ledgerResult.items||[],monthly=summaryResult.items||[],selected=new Set();let filtered=[];
