    layout(`${riskMessages.length?`<div class="invoice-risk-strip"><strong>财税风险提醒</strong><span>${riskMessages.map(esc).join('；')}</span><button class="secondary" id="invoice-risk-settings">提醒设置</button></div>`:''}<div class="invoice-filter card"><div class="invoice-filter-main"><label>日期从<input id="invoice-from" type="date" /></label><label>至<input id="invoice-to" type="date" /></label><select id="invoice-direction"><option value="">全部进销项</option><option>进项</option><option>销项</option></select><select id="invoice-project"><option value="">全部项目</option>${appState.projects.map(project=>`<option value="${project.id}">${esc(project.code)} · ${esc(project.name)}</option>`).join('')}</select><input id="invoice-keyword" placeholder="搜索发票号码、往来单位" /></div><div class="invoice-filter-actions"><button class="secondary" data-invoice-range="month">本月</button><button class="secondary" data-invoice-range="quarter">本季度</button><button class="secondary" data-invoice-range="year">本年度</button><button class="secondary" data-invoice-range="three">近 3 个月</button><button class="secondary" id="invoice-advanced-toggle">高级筛选</button><button class="primary" id="new-manual-invoice">＋ 录入发票</button></div><div class="invoice-advanced hidden" id="invoice-advanced"><input id="invoice-counterparty" list="invoice-counterparty-list" placeholder="往来单位" /><datalist id="invoice-counterparty-list">${counterparties.map(name=>`<option value="${esc(name)}"></option>`).join('')}</datalist><select id="invoice-type"><option value="">全部发票类型</option>${types.map(name=>`<option>${esc(name)}</option>`).join('')}</select><input id="invoice-tax" type="number" placeholder="税率 %" /><select id="invoice-certified"><option value="">全部认证状态</option><option>未认证</option><option>已认证</option></select><select id="invoice-booked"><option value="">全部入账状态</option><option>未入账</option><option>已入账</option></select></div></div><div class="invoice-metrics" id="invoice-metrics"></div><div class="invoice-trend card" id="invoice-trend"></div><div class="invoice-table-head"><div><h2>发票明细</h2><span class="sub" id="invoice-result-count"></span></div><div><button class="secondary" id="invoice-export">导出当前结果</button><button class="secondary" id="invoice-print">打印</button></div></div><div class="invoice-batch hidden" id="invoice-batch"><strong>已选择 <b>0</b> 张</strong><button class="secondary" data-batch-status="certified">批量标记已认证</button><button class="secondary" data-batch-status="booked">批量标记已入账</button><select id="batch-project"><option value="">修改项目归属</option>${appState.projects.map(project=>`<option value="${project.id}">${esc(project.code)} · ${esc(project.name)}</option>`).join('')}</select></div><div class="card table-wrap compact-finance-table"><table><thead><tr><th><input id="invoice-check-all" type="checkbox" /></th><th>状态</th><th>日期 / 号码</th><th>项目</th><th>往来单位</th><th>类型 / 税率</th><th class="amount-col">含税金额</th><th class="amount-col">税额</th><th>附件</th><th>操作</th></tr></thead><tbody id="invoice-optimized-body"></tbody></table></div>`);
    if(!$('#invoice-risk-settings')){const settingsButton=document.createElement('button');settingsButton.className='secondary';settingsButton.id='invoice-risk-settings';settingsButton.textContent='提醒设置';$('#invoice-advanced-toggle').after(settingsButton)}
    const dateText=date=>date.toISOString().slice(0,10),setRange=range=>{const end=new Date(),start=new Date(end);if(range==='month')start.setDate(1);if(range==='quarter')start.setMonth(Math.floor(end.getMonth()/3)*3,1);if(range==='year')start.setMonth(0,1);if(range==='three')start.setMonth(end.getMonth()-2,1);$('#invoice-from').value=dateText(start);$('#invoice-to').value=dateText(end);draw()};
