    ['invoice-from','invoice-to','invoice-direction','invoice-project','invoice-keyword','invoice-counterparty','invoice-type','invoice-tax','invoice-certified','invoice-booked'].forEach(id=>$('#'+id).oninput=draw);document.querySelectorAll('[data-invoice-range]').forEach(button=>button.onclick=()=>setRange(button.dataset.invoiceRange));$('#invoice-advanced-toggle').onclick=()=>$('#invoice-advanced').classList.toggle('hidden');$('#new-manual-invoice').onclick=()=>openInvoiceModal({});$('#invoice-export').onclick=()=>exportCsv('发票台账.csv',['方向','日期','号码','项目','往来单位','类型','税率','含税金额','税额','认证','入账'],filtered.map(item=>[item.direction,item.invoice_date,item.invoice_number,item.project_name||'',item.counterparty,item.invoice_type,item.tax_rate,item.total_amount,item.tax_amount,item.certification_status||'未认证',item.booked_status||'未入账']));$('#invoice-print').onclick=()=>window.print();$('#invoice-check-all').onchange=event=>{filtered.forEach(item=>event.target.checked?selected.add(String(item.id)):selected.delete(String(item.id)));draw()};document.querySelectorAll('[data-batch-status]').forEach(button=>button.onclick=async()=>{if(!selected.size)return;const field=button.dataset.batchStatus==='certified'?{certification_status:'已认证'}:{booked_status:'已入账'};await Promise.all([...selected].map(id=>api(`/api/invoice-ledger/${id}/status`,{method:'PATCH',body:JSON.stringify(field)})));toast('批量状态已更新');views.invoices()});$('#batch-project').onchange=async event=>{if(!selected.size||!event.target.value)return;await Promise.all([...selected].map(id=>api(`/api/invoice-ledger/${id}/project`,{method:'PATCH',body:JSON.stringify({project_id:event.target.value})})));toast('项目归属已批量更新');views.invoices()};
